('MAIDEN-HZ-AGRI', 'Trương Lộ Dao', 'Zhang Luyao', 'han_zhong', 'PEASANT', 'Nông gia hái thuốc núi Tần Lĩnh', 390, 'COM-GRAIN', 5, 'TLT-HERBAL-WISDOM', 'Dược Sơn Tuệ Tâm', '+20% EXP Trí Lực & Hồi Phục Thể Lực, +2 Base INT cho con cái', 'int', 2, 'Thôn nữ thung lũng Hán Thủy, am tường cây thuốc thảo dược núi Tần Lĩnh.', 'Herbal gatherer maiden in the valleys of Mount Qinling.', 0, 'CALM', 'FAMILY_SECURITY', 28, 54, 50, 36, 42, 54, 52, 48),
('MAIDEN-HZ-CRAFT', 'Nghiêm Tú Trâm', 'Yan Xiuzhen', 'han_zhong', 'ARTISAN_SHOP', 'Thợ chế tạo cung nỏ nỏ máy Hán Trung', 1350, 'COM-TIMBER', 6, 'TLT-CRAFT-INGENUITY', 'Xảo Xưởng Tuệ Tâm', '+15% Hiệu suất sản nghiệp, +2 Base CRA cho con cái', 'cra', 2, 'Khuê nữ xưởng cơ mộc Hán Trung, chế tạo dây cung và khóa nỏ điêu luyện.', 'Crossbow mechanical craft maiden in Hanzhong armory.', 0, 'DILIGENT', 'CRAFT_MASTERY', 32, 50, 58, 42, 40, 50, 70, 50),
('MAIDEN-HZ-GENTRY', 'Diêm Nhã Phương', 'Yan Yafang', 'han_zhong', 'GENTRY_CLAN', 'Diêm Thị Danh Môn Ba Thục', 4200, 'COM-SILK', 3, 'TLT-NOBLE-DECORUM', 'Hào Môn Lễ Giáo', '+25 Danh vọng gia tộc, +2 Base POL cho con cái', 'pol', 2, 'Thiên kim Diêm gia Hán Trung, gia giáo nề nếp, khí chất thâm trầm đoan trang.', 'Noble lady of the scholarly Yan lineage in Hanzhong commandery.', 0, 'HONORABLE', 'STABILITY', 20, 74, 58, 46, 72, 68, 44, 48),

-- Vũ Uy & Tây Lương (Wu Wei)
('MAIDEN-WW-AGRI', 'Khương Thảo Nương', 'Jiang Caoniang', 'wu_wei', 'PEASANT', 'Mục dân chăn thả ngựa cừu Lương Châu', 380, 'COM-HORSE-W', 1, 'TLT-NOMADIC-VIGOR', 'Biên Thảo Kiên Cường', '+20% EXP Võ Lực & Kháng Mệt Mỏi, +2 Base WAR cho con cái', 'war', 2, 'Mục nữ thảo nguyên Tây Lương, cưỡi ngựa như bay, tính tình bộc trực hào phóng.', 'Spirited nomadic herder maiden on the wind-swept Xiliang plains.', 0, 'VALIANT', 'FAMILY_SECURITY', 42, 40, 50, 45, 32, 46, 46, 58),
('MAIDEN-WW-CRAFT', 'Diệp Thục Trinh', 'Ye Shuzhen', 'wu_wei', 'ARTISAN_SHOP', 'Chưởng quỹ xưởng thuộc da thú Tây Vực', 1300, 'COM-LEATH', 8, 'TLT-LEATHER-CRAFT', 'Tây Vực Da Thuộc', '+15% Hiệu suất giáp da xưởng, +2 Base CRA cho con cái', 'cra', 2, 'Khuê nữ xưởng may giáp da chiến mã Vũ Uy, tay nghề khâu vá giáp trụ tinh vi.', 'Skilled leather armor artisan maiden in frontier Wuwei.', 0, 'DILIGENT', 'CRAFT_MASTERY', 30, 48, 62, 40, 38, 52, 70, 54),
('MAIDEN-WW-GENTRY', 'Lương Nguyệt Kiều', 'Liang Yueqiao', 'wu_wei', 'GENTRY_CLAN', 'Lương Châu Hào Tộc Lương Thị', 4300, 'COM-HORSE-W', 2, 'TLT-FRONTIER-NOBLE', 'Biên Cương Danh Môn', '+20% EXP Thống Soái & Võ Lực, +2 Base LDR cho con cái', 'ldr', 2, 'Thiên kim Lương thị vọng tộc đất Lương Châu, cốt cách anh hào, am tường tài chính biên giới.', 'Frontier noble maiden of the prominent Liang family in Liangzhou.', 0, 'HONORABLE', 'HEGEMONY', 35, 70, 64, 60, 65, 68, 42, 56),

-- Uyển Thành (Wan Cheng)
('MAIDEN-WC-AGRI', 'Hoàng Thu Dung', 'Huang Qiurong', 'wan_cheng', 'PEASANT', 'Nông gia bãi bồi sông Dục Thủy Nam Dương', 420, 'COM-GRAIN', 6, 'TLT-AGRI-VIRTUE', 'Điền Viên Cần Kiệm', '+25% Tốc độ hồi phục thể lực, +2 Base COM cho con cái', 'com', 2, 'Thôn nữ bãi bồi ven sông Dục Thủy, chăm chỉ đồng áng tích trữ lương thực.', 'Farming maiden on the fertile river flats near Wancheng.', 0, 'DILIGENT', 'FAMILY_SECURITY', 25, 46, 55, 36, 40, 50, 48, 52),
('MAIDEN-WC-CRAFT', 'Ân Mỹ Linh', 'Yin Meiling', 'wan_cheng', 'ARTISAN_SHOP', 'Chưởng phường lò rèn đúc sắt Nam Dương', 1480, 'COM-IRON', 8, 'TLT-IRON-SMITH', 'Nam Dương Thiết Đúc', '+15% Hiệu suất xưởng rèn, +2 Base CRA cho con cái', 'cra', 2, 'Ái nữ chưởng phường đúc sắt Nam Dương lừng danh, am hiểu các loại quặng sắt luyện kim.', 'Ironsmith craft maiden in Nanyang historic foundry center.', 0, 'DILIGENT', 'CRAFT_MASTERY', 32, 50, 62, 40, 40, 54, 72, 50),
('MAIDEN-WC-GENTRY', 'Đặng Du Khanh', 'Deng Youqing', 'wan_cheng', 'GENTRY_CLAN', 'Nam Dương Đặng Thị Thế Tộc', 4700, 'COM-SILK', 4, 'TLT-NOBLE-DECORUM', 'Hào Môn Lễ Giáo', '+25 Danh vọng gia tộc, +2 Base POL cho con cái', 'pol', 2, 'Thiên kim Đặng thị Nam Dương (dòng dõi Đặng Vũ khai quốc khai cơ), đoan trang lễ nghi.', 'Aristocratic daughter of the Deng clan in Nanyang.', 0, 'HONORABLE', 'STABILITY', 22, 75, 60, 48, 74, 72, 42, 48),

-- Kế Thành & Bắc Bình (Ji Cheng)
('MAIDEN-JC-AGRI', 'Hàn Tố Nương', 'Han Suniang', 'ji_cheng', 'PEASANT', 'Nông gia trồng lúa mạch vùng hàn bắc', 400, 'COM-GRAIN', 5, 'TLT-FROST-RESILIENCE', 'Phong Tuyết Can Trường', '+20% EXP Võ Lực & Sức Bền, +2 Base WAR cho con cái', 'war', 2, 'Thôn nữ vùng giá buốt Kế Thành U Châu, chịu đựng gió rét dẻo dai kiên cường.', 'Peasant maiden resilient against northern frost near Jicheng.', 0, 'DILIGENT', 'FAMILY_SECURITY', 35, 44, 52, 40, 35, 48, 46, 54),
('MAIDEN-JC-CRAFT', 'Liễu Tú Anh', 'Liu Xiuying', 'ji_cheng', 'ARTISAN_SHOP', 'Thợ chế tạo yên cương chiến mã Bắc Bình', 1380, 'COM-LEATH', 5, 'TLT-HARNESS-MAKER', 'Bắc Bình Mã Cụ', '+15% Hiệu suất chế tạo trang bị, +2 Base CRA cho con cái', 'cra', 2, 'Khuê nữ xưởng yên cương ngựa chiến Bắc Bình, rành rẽ da thuộc và thiết giáp kỵ binh.', 'Saddlery craft maiden serving northern cavalry regiments.', 0, 'PRAGMATIC', 'CRAFT_MASTERY', 28, 52, 60, 44, 38, 54, 68, 52),
('MAIDEN-JC-GENTRY', 'Công Tôn Nhược Yến', 'Gongsun Ruoyan', 'ji_cheng', 'GENTRY_CLAN', 'Công Tôn Thị Chi Tộc Bắc Bình', 4500, 'COM-HORSE-W', 2, 'TLT-WHITE-HORSE-HERITAGE', 'Bạch Mã Khí Phách', '+25% EXP Kỵ Binh & Thống Soái, +2 Base LDR cho con cái', 'ldr', 2, 'Khuê tú chi tộc Công Tôn thị, am hiểu chiến mã thảo nguyên và thuật bắn cung trên lưng ngựa.', 'Noble maiden of the Gongsun clan famous for White Horse cavalry.', 0, 'VALIANT', 'HEGEMONY', 38, 68, 58, 62, 60, 65, 44, 55),

-- Xích Bích & Sài Tang (Chi Bi)
('MAIDEN-CB-AGRI', 'Sở Tiêu Tiêu', 'Chu Xiaoxiao', 'chi_bi', 'PEASANT', 'Nông gia hái dâu nuôi tằm ven hồ Bà Dương', 410, 'COM-GRAIN', 5, 'TLT-SERICULTURE', 'Bà Dương Tang Ma', '+20% EXP Thương Nghiệp, +2 Base COM cho con cái', 'com', 2, 'Nữ tử hiền dịu ven hồ Bà Dương, hái dâu nuôi tằm, chất phác thuần hậu.', 'Sericulture peasant maiden beside Poyang Lake.', 0, 'CALM', 'FAMILY_SECURITY', 22, 45, 55, 35, 38, 54, 50, 50),
('MAIDEN-CB-CRAFT', 'Tần Diễm Nương', 'Qin Yannian', 'chi_bi', 'ARTISAN_SHOP', 'Đại sư đúc đồng và chuông đồng Sài Tang', 1500, 'COM-IRON', 6, 'TLT-BRONZE-ART', 'Sài Tang Đồng Đúc', '+15% Hiệu suất sản nghiệp, +2 Base CRA cho con cái', 'cra', 2, 'Ái nữ nghệ nhân đúc đồng Sài Tang, rành rẽ kim khí và phối trộn đồng thiếc.', 'Bronze foundry craft maiden in Saitang lakeside port.', 0, 'DILIGENT', 'CRAFT_MASTERY', 24, 52, 62, 40, 42, 56, 70, 52),
('MAIDEN-CB-GENTRY', 'Lục Giai Tuệ', 'Lu Jiahui', 'chi_bi', 'GENTRY_CLAN', 'Ngô Quận Lục Thị Vọng Tộc', 4900, 'COM-SILK', 4, 'TLT-HARMONIOUS-AESTHETIC', 'Giang Nam Cầm Vận', '+20% Sĩ Khí Gia Tộc, +2 Base DIP cho con cái', 'dip', 2, 'Danh viện Lục gia Giang Nam, dung mạo tú nhã, ngón đàn cổ tranh nức tiếng ven hồ.', 'Graceful aristocrat of the prominent Lu clan in Jiangnan.', 0, 'BENEVOLENT', 'PEACE', 20, 75, 60, 48, 70, 76, 44, 46),

-- Thọ Xuân (Shou Chun)
('MAIDEN-SC-AGRI', 'Diệp Thải Vi', 'Ye Caiwei', 'shou_chun', 'PEASANT', 'Nông hộ trồng lúa nước đầm lầy Hoài Nam', 430, 'COM-GRAIN', 6, 'TLT-LOTUS-SERENITY', 'Hoài Nam Thủy Hương', '+20% Sĩ Khí Gia Tộc, +2 Base DIP cho con cái', 'dip', 2, 'Thôn nữ hái củ ấu đầm nước Hoài Nam, tính cách nhu mì đôn hậu.', 'Water chestnut harvester maiden in fertile Huainan marshes.', 0, 'CALM', 'FAMILY_SECURITY', 24, 46, 54, 36, 40, 56, 48, 50),
('MAIDEN-SC-CRAFT', 'Trịnh Mỹ Châu', 'Zheng Meizhou', 'shou_chun', 'ARTISAN_SHOP', 'Chủ phường ủ rượu hoa cúc Thọ Xuân', 1520, 'COM-WINE', 4, 'TLT-BREWING-ART', 'Cúc Hoa Rượu Nghệ', '+15% Hiệu suất sản nghiệp, +2 Base CRA cho con cái', 'cra', 2, 'Khuê nữ xưởng nấu mỹ tửu Thọ Xuân, nắm giữ bí thuật ủ men rượu cúc thơm ngát.', 'Brewmaster maiden crafting prized chrysanthemum wine in Shouchun.', 0, 'PRAGMATIC', 'WEALTH', 22, 54, 66, 40, 42, 60, 70, 52),
('MAIDEN-SC-GENTRY', 'Viên Tố Đình', 'Yuan Suding', 'shou_chun', 'GENTRY_CLAN', 'Hoài Nam Viên Thị Chi Tộc', 5100, 'COM-SILK', 4, 'TLT-NOBLE-DECORUM', 'Hào Môn Lễ Giáo', '+25 Danh vọng gia tộc, +2 Base POL cho con cái', 'pol', 2, 'Tiểu thư Viên thị Hoài Nam (chi tộc Viên Thuật), phong tư cao nhã, cẩm y ngọc thực.', 'Highborn lady of the Yuan clan branch in Shouchun.', 0, 'HONORABLE', 'HEGEMONY', 20, 74, 64, 48, 72, 74, 42, 46);

-- 3. Historical Heroines in Master Characters
INSERT OR REPLACE INTO master_characters (
  npc_id, name_vi, name_en, name_han, style_name_vi, style_name_en,
  birth_year, baseline_age, baseline_location, baseline_position_vi, baseline_position_en,
  int_attr, pol_attr, war_attr, ldr_attr, dip_attr, com_attr, log_attr, cra_attr,
  personality, motivation, baseline_sentiment_player, core_associates, talents, bio_vi, bio_en
) VALUES
('NPC-0151', 'Vương Nguyên Cơ', 'Wang Yuanji', '王元姬', 'Văn Minh', 'Wenming', 217, 20, 'LOC-0005', 'Danh Môn Khuê Tú', 'Highborn Noblewoman', 84, 88, 35, 55, 76, 65, 72, 60, 'HONORABLE', 'FAMILY_SECURITY', 20, '["NPC-0012"]', '["TLT-VIRTUOUS-FORESIGHT", "CLASSICAL_SCHOLAR"]', 'Vương Nguyên Cơ là con gái Vương Túc, cháu nội danh sĩ Vương Lãng. Nổi tiếng thông tuệ đoan nghiêm, nhìn xa trông rộng, có tài thấu triệt lòng người.', 'Wang Yuanji, daughter of Wang Su and granddaughter of Wang Lang, famous for her intellect, virtue, and political foresight.'),
('NPC-0152', 'Lữ Linh Khởi', 'Lu Lingqi', '吕玲绮', 'Chiến Cơ', 'Zhanji', 180, 19, 'LOC-0012', 'Hổ Nữ Sa Trường', 'Fierce Martial Maiden', 52, 38, 88, 78, 45, 40, 55, 50, 'VALIANT', 'MARTIAL_GLORY', 15, '["NPC-0002"]', '["TLT-WAR-HERITAGE", "HALBERD_MASTERY"]', 'Con gái Chiến thần Lữ Bố, kế thừa dũng lực kinh người và tuyệt kỹ Phương Thiên Họa Kích, kiêu dũng quả cảm nơi sa trường.', 'Daughter of Lu Bu, inherited her fathers immense physical might and halberd prowess, fearless in battlefield engagements.'),
('NPC-0153', 'Bộ Luyện Sư', 'Bu Lianshi', '步练师', 'Khang Hòa', 'Kanghe', 185, 21, 'LOC-0013', 'Giang Đông Đệ Nhất Hiền', 'Virtuous Lady of Jiangdong', 75, 76, 30, 50, 85, 68, 60, 55, 'BENEVOLENT', 'HARMONY', 25, '["NPC-0087", "NPC-0088"]', '["TLT-SERENE-BENEVOLENCE", "DIPLOMATIC_GRACE"]', 'Ái thê của Ngô Đại Đế Tôn Quyền, tính tình khoan dung hòa nhã, chưa từng đố kỵ, được lục cung và quần thần tôn kính.', 'Beloved consort of Sun Quan, renowned throughout Jiangdong for her modesty, benevolence, and serene disposition.'),
('NPC-0154', 'Mã Vân Lục', 'Ma Yunlu', '马云禄', 'Tây Lương Kiêu Cơ', 'Xiliang Maiden', 186, 19, 'LOC-0023', 'Tây Lương Hổ Nữ', 'Frontier Warrior Maiden', 60, 42, 85, 75, 55, 48, 62, 52, 'VALIANT', 'JUSTICE', 20, '["NPC-0005"]', '["TLT-CAVALRY-PROWESS", "SPEAR_DANCE"]', 'Ái nữ Tây Lương Thái thú Mã Đằng, muội muội Mã Siêu. Sinh ra nơi biên ải phong tuyết, tinh thông cưỡi ngựa bắn cung và thương pháp linh diệu.', 'Daughter of Ma Teng and sister of Ma Chao, raised on the rugged frontier with elite equestrian archery and martial mastery.'),
('NPC-0155', 'Quan Ngân Bình', 'Guan Yinping', '关银屏', 'Quan Tam Nương', 'Sanniang', 190, 18, 'LOC-0014', 'Kinh Châu Hổ Nữ', 'Tiger Maiden of Jingzhou', 65, 50, 82, 74, 58, 45, 58, 48, 'HONORABLE', 'FAMILY_HONOR', 25, '["NPC-0003"]', '["TLT-AZURE-WILL", "BLADE_MASTERY"]', 'Tam ái nữ của Hán Thọ Đình Hầu Quan Vũ, kế thừa thần khí kiên định và đao pháp Thanh Long, tính cách bất khuất hào sảng.', 'Third daughter of Guan Yu, inheritor of the Azure Dragon blade tradition, famous for her uncompromising spirit and filial valor.'),
('NPC-0156', 'Tân Hiến Anh', 'Xin Xianying', '辛宪英', 'Minh Giám', 'Mingjian', 191, 22, 'LOC-0005', 'Đệ Nhất Minh Tuệ Nữ Sĩ', 'Foremost Scholar Strategist', 88, 86, 28, 52, 82, 60, 70, 54, 'SCHOLARLY', 'WISDOM', 20, '["NPC-0012"]', '["TLT-ASTUTE-PERCEPTION", "FORESIGHT"]', 'Con gái mưu sĩ Tân Bình, nức danh là đệ nhất nữ trí giả Tào Ngụy. Từng nhiều lần đoán định chuẩn xác cục diện chính biến và chiến trường.', 'Daughter of Xin Ping, widely acclaimed as the sharpest female intellect of Cao Wei, renowned for uncanny strategic predictions.'),
('NPC-0157', 'Trâu Thị', 'Lady Zou', '邹氏', 'Khuynh Thành', 'Qingcheng', 175, 25, 'LOC-0015', 'Nam Dương Quả Phụ', 'Noble Widow of Nanyang', 70, 55, 25, 40, 88, 72, 50, 58, 'PRAGMATIC', 'SURVIVAL', 15, '[]', '["TLT-CAPTIVATING-GRACE", "SEDUCTION"]', 'Tuyệt sắc phu nhân góa phụ của Trương Tế tại Uyển Thành, dung mạo diễm lệ khuynh thành, am hiểu giao tiếp dạ yến.', 'Widow of Zhang Ji in Wancheng, blessed with peerless elegance and social charm that captivated commanders across the realm.'),
('NPC-0158', 'Phàn Thị', 'Lady Fan', '樊氏', 'Tiết Phụ', 'Xiefu', 178, 24, 'LOC-0020', 'Quế Dương Quốc Sắc', 'Belle of Guiyang', 72, 62, 30, 45, 78, 66, 54, 60, 'HONORABLE', 'FAMILY_SECURITY', 20, '[]', '["TLT-PURE-INTEGRITY", "VIRTUE"]', 'Quả phụ Triệu Phạm tại Quế Dương Kinh Nam, quốc sắc thiên hương nhưng trọng nghĩa khinh lợi, giữ tiết tháo kiên trinh.', 'Sister-in-law of Zhao Fan in southern Jingzhou, famed for her resplendent beauty and unyielding moral dignity.'),
('NPC-0159', 'Mi Phu Nhân', 'Lady Mi', '麋氏', 'Liệt Nữ', 'Lienu', 182, 23, 'LOC-0014', 'Từ Châu Danh Viện', 'Consort of Xu Province Lineage', 68, 60, 32, 54, 72, 75, 65, 55, 'HONORABLE', 'FAMILY_LOYALTY', 25, '["NPC-0141"]', '["TLT-SACRIFICIAL-LOYALTY", "MERCHANT_LINEAGE"]', 'Muội muội của đại cự thương Mi Trúc Từ Châu, thứ thê của Lưu Bị. Khí chất đoan trang dũng liệt, trọng đại cục gia tộc.', 'Sister of grand merchant Mi Zhu and consort to Liu Bei, combining commercial magnate heritage with resolute self-sacrifice.'),
('NPC-0160', 'Cam Phu Nhân', 'Lady Gan', '甘氏', 'Chiêu Liệt', 'Zhaolie', 184, 22, 'LOC-0010', 'Ngọc Khiết Phu Nhân', 'Virtuous Consort of Han', 65, 64, 22, 48, 76, 60, 58, 58, 'BENEVOLENT', 'PEACE', 25, '[]', '["TLT-EMPRESS-GRACE", "JADE_PURITY"]', 'Thê thất Lưu Bị, thân mẫu Lưu Thiện (A Đẩu). Da thịt trắng ngần như ngọc, tính tình dịu dàng từ ái, chủ trì nội trạch thuận hòa.', 'Consort to Liu Bei and mother of Liu Shan, praised for her porcelain grace, gentle nature, and harmonious domestic leadership.');
